typedef unsigned int u_int;

struct nglTexture;
struct nglQuad
{
    unsigned char data[104];
};

extern bool nvlMPEGAdvance();
extern void nglInitQuad(nglQuad *Quad);
extern void nglSetQuadBlend(nglQuad *Quad, u_int Blend, u_int Constant = 0);
extern void nglSetQuadMapFlags(nglQuad *Quad, u_int MapFlags);
extern void nglSetQuadTex(nglQuad *Quad, nglTexture *Tex);
extern int nglGetScreenWidth();
extern int nglGetScreenHeight();
extern void nglSetQuadRect(nglQuad *Quad, float x1, float y1, float x2, float y2);
extern void nglSetQuadZ(nglQuad *Quad, float z);
extern void nglListAddQuad(nglQuad *Quad);
extern void nglListSend(bool Flip);

enum
{
    NGLBM_OPAQUE = 0,
    NGLMAP_BILINEAR_FILTER = 0x2,
    NGLMAP_CLAMP_U = 0x10,
    NGLMAP_CLAMP_V = 0x20
};

class movieplayer
{
    void *singleton_vtable;
    bool hiRes;
    unsigned char db_and_movies[580];
    nglTexture *texture;
    nglQuad frame;
    bool movieStarted;
    bool isPlaying;

public:
    void end_frame(bool flip, bool listSend);
};

void movieplayer::end_frame(bool flip, bool listSend)
{
  if(hiRes && isPlaying)
    isPlaying = nvlMPEGAdvance();
  else if (isPlaying)
  {
      nglInitQuad( &frame );
      nglSetQuadBlend( &frame, NGLBM_OPAQUE, 0 );
      nglSetQuadMapFlags(&frame, NGLMAP_CLAMP_U | NGLMAP_CLAMP_V | NGLMAP_BILINEAR_FILTER);
      nglSetQuadTex( &frame, texture );
      nglSetQuadRect( &frame, 0.0f, 0.0f, nglGetScreenWidth(),  nglGetScreenHeight());
    nglSetQuadZ(&frame, 800.0f);
      nglListAddQuad( &frame );
    if(listSend)
        nglListSend( flip );
  }
}
